Parser LL.ejemplo:
// Descenso recursivo LL(1) para: Expr -> Term ('+' Term)*
AST* parse_expr() {
  AST* node = parse_term();
  while (peek().type == TOK_PLUS) {
    consume(TOK_PLUS);
    node = new BinaryOp('+', node, parse_term());
  }
  return node;
}

Runtime y garbage collector.ejemplo:
// Go runtime: reducir presión al GC reutilizando slices en heap
var bufPool = sync.Pool{
    New: func() any { return make([]byte, 0, 4096) },
}
func process() {
    b := bufPool.Get().([]byte)[:0]
    defer bufPool.Put(b)
}

