// Tipado estático con sum type (Rust): exhaustividad verificada al compilar
enum Result {
    Ok(i32),
    Err(&'static str),
}
fn to_int(r: Result) -> i32 {
    match r { Result::Ok(v) => v, Result::Err(_) => 0 }
}

Tabla de símbolos.ejemplo:
// Búsqueda léxica en cadena de ámbitos
Symbol* lookup(Scope* scope, SymbolID name) {
    for (Scope* cur = scope; cur != NULL; cur = cur->parent) {
        Symbol* sym = map_get(cur->table, name);
        if (sym != NULL) return sym;
    }
    return NULL;
}

